    buy_book = []  # List of (price, arrival_time, id, qty_remaining)
    sell_book = []  # List of (price, arrival_time, id, qty_remaining)
    order_index = {}  # Maps id to (side, index_in_book) for quick lookup
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_index:
                side, book_idx = order_index[order_id]
                if side == 'buy':
                    # Mark as cancelled by setting qty to 0
                    price, arr_time, oid, qty = buy_book[book_idx]
                    buy_book[book_idx] = (price, arr_time, oid, 0)
                else:
                    price, arr_time, oid, qty = sell_book[book_idx]
                    sell_book[book_idx] = (price, arr_time, oid, 0)
                del order_index[order_id]

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]

            if side == 'buy':
                # Match against sell_book (lowest price first, then earliest arrival)
                sell_book.sort(key=lambda x: (x[0], x[1]))
                for i in range(len(sell_book)):
                    if qty == 0:
                        break
                    price, arr_time, sell_id, sell_qty = sell_book[i]
